//   print them
// Same sentence in, same code out. Change the sentence, not this file.

use std::collections::HashSet;
use std::error::Error;
use std::fs;

pub fn run() -> Result<(), Box<dyn Error>> {
    // read the lines of "emails.txt"  [read_lines/collect + propagate]
    let lines = fs::read_to_string("emails.txt").map(|text| text.lines().map(str::to_owned).collect::<Vec<_>>())?;
    // trim them  [trim/trim]
    let lines: Vec<String> = lines.iter().map(|l| l.trim().to_owned()).collect();
    // skip blank lines  [skip_blank/filter]
    let mut lines = lines;
    lines.retain(|l| !l.trim().is_empty());
    // remove duplicates  [dedupe/keep_order]
    let mut seen = HashSet::new();
    lines.retain(|item| seen.insert(item.clone()));
    // print them  [print/each_line]
    for line in &lines {
        println!("{line}");
    }
    Ok(())
}
